import { loadFont as loadMono } from "@remotion/google-fonts/JetBrainsMono";
import { loadFont as loadManrope } from "@remotion/google-fonts/Manrope";
import { loadFont } from "@remotion/google-fonts/Oswald";
import React, { useEffect, useId, useLayoutEffect, useMemo } from "react";
import { AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig } from "remotion";

// Chrome parks a glyph raster on a whole pixel vertically for as long as the
// matrix that carries it is axis-aligned, so text under a slow transform
// clicks along pixel by pixel. A lean too small to see takes it off that grid.
//
// A transform that carries text is marked, and told when it moves:
//
//   const glide = useGlide();
//   transform: `scale(${s})${glide(moving)}`
//
// The mark changes nothing by itself. After every frame the blocks of text
// under a marked transform get the lean: each about its own centre, and each
// by no more than its size on the screen needs. A card, a hairline or an image
// is fine under a transform as it is, so they stay level.
//
// Text leans while its transform moves, and it keeps the lean at rest when it
// rests off the pixel grid (a scene shown smaller in a player, a camera that
// holds at 1.03): dropping the lean there would snap it to the nearest pixel,
// up to half a pixel in one frame, and picking it up would snap it back. Text
// that rests on the grid loses the lean without moving, so a scene at rest at
// full size is drawn exactly as it would be without any of this.

/**
 * Returns `glide(moving)`: append it to a transform that carries text, with
 * `moving` true on the frames where that transform changes.
 *
 * Everything else lives inside this one closure: the build of Studio
 * elements pastes this file whole into the component that uses it, where a
 * second `LEAN` or `lean` at the top level would collide.
 */
const useGlide = (() => {
  /** What `glide(false)` adds to a transform: an identity matrix, to find it by. */
  const AT_REST = " matrix(1, 0, 0, 1, 0, 0)";
  /** `glide(true)` adds it twice. */
  const MOVING = AT_REST + AT_REST;
  const MARKED = `[style*="${AT_REST.trim()}"]`;
  // Text leaves the grid once the matrix leans x into y by half of 1/1024 in
  // device pixels (Skia rounds the glyph matrix to 1/1024). A fifth over it.
  const LEAN = 0.6 / 1024;
  // Past this the text is a speck on the screen; it is left alone.
  const STEEPEST = 5;
  // How far from a whole pixel text may rest and still count as on the grid:
  // the jump it makes when the lean goes is no bigger than this.
  const ON_GRID = 0.05;

  /** The linear part of a 2D matrix: x' = a·x + c·y, y' = b·x + d·y. */
  type Lin = [a: number, b: number, c: number, d: number];
  const LEVEL: Lin = [1, 0, 0, 1];
  const times = (m: Lin, n: Lin): Lin => [
    m[0] * n[0] + m[2] * n[1],
    m[1] * n[0] + m[3] * n[1],
    m[0] * n[2] + m[2] * n[3],
    m[1] * n[2] + m[3] * n[3],
  ];
  const turned = (degrees: number): Lin => {
    const t = (degrees * Math.PI) / 180;
    return [Math.cos(t), Math.sin(t), -Math.sin(t), Math.cos(t)];
  };
  const offWhole = (n: number) => Math.abs(n - Math.round(n));

  type Block = HTMLElement | SVGTextElement | SVGSVGElement;
  let leant: Block[] = [];
  // Fonts arrive after the first pass and change what is laid out where, with
  // no render to follow: a block or a marked element that changes size is read
  // again before the frame is painted.
  let watcher: ResizeObserver | undefined;
  const watched = new WeakSet<Element>();
  const watch = (el: Element) => {
    if (watched.has(el)) return;
    watched.add(el);
    watcher ??= new ResizeObserver(() => lean());
    watcher.observe(el);
  };

  const depthOf = (el: Element) => {
    let depth = 0;
    for (let up = el.parentElement; up; up = up.parentElement) depth += 1;
    return depth;
  };

  /** The nearest box around a text node that a transform applies to. */
  const blockOf = (node: Node): Block | null => {
    for (let el = node.parentElement; el; el = el.parentElement) {
      if (el instanceof SVGElement) {
        const text = el.closest("text");
        if (!(text instanceof SVGTextElement)) return null;
        // Text that only shapes a mask or a clip is not drawn where it stands
        // and cannot turn by itself: its whole drawing leans for it.
        if (!text.closest("defs, mask, clipPath, pattern, symbol, marker"))
          return text;
        let drawing = text.ownerSVGElement;
        while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
        return drawing;
      }
      if (!(el instanceof HTMLElement)) continue;
      const { display } = getComputedStyle(el);
      if (display !== "inline" && display !== "contents") return el;
    }
    return null;
  };

  /** One pass over the page: what every element's own transforms do. */
  function reader(given: Map<Element, number>) {
    type Own = {
      /** `scale` and `transform`, without the `rotate` property. */
      lin: Lin;
      /** `rotate`, in degrees: a lean given in this pass, or the scene's own. */
      turn: number;
      /** How far down it is moved, and by what whole factor it is scaled from
       * its top left corner; null when it does anything else. */
      carry: { dy: number; k: number } | null;
    };
    const lens = new Map<Element, boolean>();
    /** Whether an element shows its children in perspective. */
    const lensOn = (el: Element | null): boolean => {
      if (!el) return false;
      const seen = lens.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const result =
        style.perspective !== "none" ||
        (style.transformStyle === "preserve-3d" && lensOn(el.parentElement));
      lens.set(el, result);
      return result;
    };
    const own = new Map<Element, Own | null>();
    const ownOf = (el: Element): Own | null => {
      const seen = own.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const m = new DOMMatrixReadOnly(
        style.transform === "none" ? "" : style.transform,
      );
      const scale = style.scale === "none" ? [] : style.scale.split(" ");
      const sx = scale.length ? Number.parseFloat(scale[0]) : 1;
      const sy = scale.length > 1 ? Number.parseFloat(scale[1]) : sx;
      const rotate = style.rotate === "none" ? [] : style.rotate.split(" ");
      let result: Own | null = null;
      // Seen in perspective, text is drawn on a layer of its own: not ours. A
      // turn out of the plane without perspective lands flat on the screen,
      // and text under it snaps like any other.
      // A push along z alone, or a half turn, leaves it flat even under a lens.
      const inPerspective =
        Math.max(Math.abs(m.m14), Math.abs(m.m24), Math.abs(m.m34)) > 1e-9 ||
        (Math.max(
          Math.abs(m.m13),
          Math.abs(m.m31),
          Math.abs(m.m23),
          Math.abs(m.m32),
        ) > 1e-6 &&
          lensOn(el.parentElement));
      if (!inPerspective && rotate.length < 2) {
        // The `scale` property acts on what `transform` has produced.
        const lin: Lin = [m.a * sx, m.b * sy, m.c * sx, m.d * sy];
        const moved =
          style.translate === "none"
            ? 0
            : (style.translate.split(" ")[1] ?? "0px");
        const k = Math.round(lin[0]);
        const whole =
          m.is2D &&
          k >= 1 &&
          Math.abs(lin[0] - k) < 1e-4 &&
          Math.abs(lin[3] - k) < 1e-4 &&
          Math.abs(lin[1]) < 1e-5 &&
          Math.abs(lin[2]) < 1e-5 &&
          rotate.length === 0 &&
          (moved === 0 || moved.endsWith("px")) &&
          // Scaled about its corner, a box stays where layout put it.
          (k === 1 || /^0(px)? 0(px)?/.test(style.transformOrigin));
        result = {
          lin,
          turn: rotate.length ? Number.parseFloat(rotate[0]) : 0,
          carry: whole
            ? { dy: sy * m.f + (moved === 0 ? 0 : Number.parseFloat(moved)), k }
            : null,
        };
      }
      own.set(el, result);
      return result;
    };
    const down = new Map<Element, Lin | null>();
    /** Everything from the page down to and including this element. */
    const linDown = (el: Element | null): Lin | null => {
      if (!el) return LEVEL;
      const seen = down.get(el);
      if (seen !== undefined) return seen;
      const above = linDown(el.parentElement);
      const mine = above && ownOf(el);
      const result =
        above && mine
          ? times(times(above, turned(given.get(el) ?? mine.turn)), mine.lin)
          : null;
      down.set(el, result);
      return result;
    };
    const carried = new Map<Element, { dy: number; k: number } | null>();
    const carryDown = (
      el: Element | null,
    ): { dy: number; k: number } | null => {
      if (!el) return { dy: 0, k: 1 };
      const seen = carried.get(el);
      if (seen !== undefined) return seen;
      const above = carryDown(el.parentElement);
      const mine = above && !given.has(el) ? ownOf(el)?.carry : null;
      const result =
        above && mine
          ? { dy: above.dy + above.k * mine.dy, k: above.k * mine.k }
          : null;
      carried.set(el, result);
      return result;
    };
    return { ownOf, linDown, carryDown };
  }

  /**
   * Whether text in an SVG rests on the grid: it is placed wherever it is told
   * to, so only when it is shown one to one and its baseline happens to land on
   * a whole pixel. `lands` is where its own space lands on the screen.
   */
  function restsOnGrid(text: SVGTextElement, lands: DOMMatrix | null) {
    if (!lands) return false;
    const dpr = window.devicePixelRatio;
    const style = getComputedStyle(text);
    const k = lands.d * dpr;
    const y = text.y.baseVal.numberOfItems
      ? text.y.baseVal.getItem(0).value
      : 0;
    return (
      text.y.baseVal.numberOfItems <= 1 &&
      text.dy.baseVal.numberOfItems === 0 &&
      !text.querySelector("tspan[y], tspan[dy], textPath") &&
      /^(auto|alphabetic)$/.test(style.dominantBaseline) &&
      /^(auto|baseline)$/.test(style.alignmentBaseline) &&
      Math.abs(lands.b) < 1e-6 &&
      Math.abs(lands.c) < 1e-6 &&
      Math.round(k) >= 1 &&
      offWhole(k) < 2e-3 &&
      offWhole((lands.d * y + lands.f) * dpr) < ON_GRID
    );
  }

  /**
   * The angle that takes a block off the grid, given what is above it (`above`)
   * and what its own transform does (`own`), both in device pixels: the lean is
   * a turn between the two. 0 when the block leans enough as it is, null when
   * no sane angle would do.
   */
  function angleFor(above: Lin, own: Lin): number | null {
    // y from x of `above · turn(θ) · own` is p·sin θ + q·cos θ.
    const p = above[3] * own[0] - above[1] * own[1];
    const q = above[1] * own[0] + above[3] * own[1];
    if (Math.abs(q) >= LEAN) return 0;
    if (Math.abs(p) < 1e-9) return null;
    // Along the turn the scene already has, so the two never cancel out.
    const sine = ((q < 0 ? -LEAN : LEAN) - q) / p;
    if (Math.abs(sine) > Math.sin((STEEPEST * Math.PI) / 180)) return null;
    return (Math.asin(sine) * 180) / Math.PI;
  }

  function lean() {
    for (const el of leant) {
      el.style.removeProperty("rotate");
      if (el instanceof SVGElement) el.style.removeProperty("translate");
    }
    leant = [];
    const zones = document.querySelectorAll<HTMLElement | SVGElement>(MARKED);
    if (zones.length === 0) return;
    // Each block of text under a mark, and whether any transform above it moves.
    const blocks = new Map<Block, boolean>();
    // The texts a whole drawing leans for.
    const standsFor = new Map<SVGSVGElement, SVGTextElement[]>();
    for (const zone of zones) {
      const moving = zone.style.transform.includes(MOVING.trim());
      const walker = document.createTreeWalker(zone, NodeFilter.SHOW_TEXT);
      for (let node = walker.nextNode(); node; node = walker.nextNode()) {
        if (!/\S/.test(node.nodeValue ?? "")) continue;
        const block = blockOf(node);
        // A block that turns by a property of its own is left to the scene.
        if (!block || block.style.rotate) continue;
        blocks.set(block, moving || (blocks.get(block) ?? false));
        const text = node.parentElement?.closest("text");
        if (block instanceof SVGSVGElement && text instanceof SVGTextElement)
          standsFor.set(block, [...(standsFor.get(block) ?? []), text]);
      }
      watch(zone);
    }
    for (const block of blocks.keys()) watch(block);
    const dpr = window.devicePixelRatio;
    const scaled = (m: Lin): Lin => [
      m[0] * dpr,
      m[1] * dpr,
      m[2] * dpr,
      m[3] * dpr,
    ];
    // Outer blocks first: a block inside a leaning one takes only what it
    // still lacks, so leans never pile up. Everything is read before anything
    // is written; `given` stands in for the leans not yet on the page.
    const given = new Map<Element, number>();
    const { ownOf, linDown, carryDown } = reader(given);
    const writes: (() => void)[] = [];
    const ordered = [...blocks.keys()].sort((a, b) => depthOf(a) - depthOf(b));
    for (const el of ordered) {
      const moving = blocks.get(el) === true;
      if (el instanceof HTMLElement) {
        const above = linDown(el.parentElement);
        const mine = ownOf(el);
        if (!above || !mine) continue;
        if (!moving) {
          // Layout puts a baseline on a whole pixel wherever the box itself
          // sits, so text is on the grid when the transforms around it only
          // move it by whole pixels and show it one to one (or two, or three).
          const carry = carryDown(el);
          if (
            carry &&
            offWhole(carry.k * dpr) < 2e-3 &&
            offWhole(carry.dy * dpr) < ON_GRID
          )
            continue;
        }
        const angle = angleFor(scaled(above), mine.lin);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      if (el instanceof SVGSVGElement) {
        // A whole drawing: what it does itself is its own transform and the
        // scale of its viewBox, read off where it lands on the screen.
        const above = linDown(el.parentElement);
        const lands = el.getScreenCTM();
        const det = above ? above[0] * above[3] - above[1] * above[2] : 0;
        if (!above || !lands || Math.abs(det) < 1e-12) continue;
        if (
          !moving &&
          (standsFor.get(el) ?? []).every((text) =>
            restsOnGrid(text, text.getScreenCTM()),
          )
        )
          continue;
        const mine = times(
          [above[3] / det, -above[1] / det, -above[2] / det, above[0] / det],
          [lands.a, lands.b, lands.c, lands.d],
        );
        const angle = angleFor(scaled(above), mine);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      // Its drawing leans as a whole already.
      let drawing = el.ownerSVGElement;
      while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
      if (drawing && given.has(drawing)) continue;
      // Text in an SVG is placed wherever it is told to, so it is on the grid
      // only when its baseline happens to land on a whole pixel.
      const frame = el.parentNode;
      if (!(frame instanceof SVGGraphicsElement) || el.style.translate)
        continue;
      const outer = frame.getScreenCTM();
      const whole = el.getScreenCTM();
      if (
        !outer ||
        !whole ||
        Math.abs(outer.a * outer.d - outer.b * outer.c) < 1e-12
      )
        continue;
      // What the text element itself does, in the space it is placed in.
      const mine = outer.inverse().multiply(whole);
      if (!moving && restsOnGrid(el, whole)) continue;
      const angle = angleFor(scaled([outer.a, outer.b, outer.c, outer.d]), [
        mine.a,
        mine.b,
        mine.c,
        mine.d,
      ]);
      if (!angle) continue;
      // An SVG element turns about the corner of its drawing. A move brings
      // the turn to the middle of the text instead.
      const box = el.getBBox();
      const [cx, cy] = [box.x + box.width / 2, box.y + box.height / 2];
      const [px, py] = [
        mine.a * cx + mine.c * cy + mine.e,
        mine.b * cx + mine.d * cy + mine.f,
      ];
      const [cos, sin] = [turned(angle)[0], turned(angle)[1]];
      const [tx, ty] = [px - (px * cos - py * sin), py - (px * sin + py * cos)];
      writes.push(() => {
        el.style.setProperty("rotate", `${angle}deg`);
        el.style.setProperty("translate", `${tx}px ${ty}px`);
      });
      leant.push(el);
    }
    for (const write of writes) write();
  }

  const useFrameEffect =
    typeof window === "undefined" ? useEffect : useLayoutEffect;

  function useGlide() {
    // No dependencies: the lean follows whatever this frame laid out.
    useFrameEffect(lean);
    return glide;
  }

  const glide = (moving: boolean) => (moving ? MOVING : AT_REST);

  return useGlide;
})();

const { fontFamily: display } = loadFont("normal", {
  weights: ["500"],
  subsets: ["latin"],
});
const { fontFamily: mono } = loadMono("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
const manrope = loadManrope("normal", {
  weights: ["600"],
  subsets: ["latin"],
});

const REMOCN_R_PATH =
  "M 0.01 0.81 C 0.01 1.73, 0.36 2.79, 1.09 4.13 C 4.91 11.04, 13.45 17.16, 21.7 18.9 C 22.94 19.16, 23.18 19.16, 51.39 19.27 C 76.07 19.36, 80.02 19.4, 81.32 19.57 C 89.89 20.69, 96.2 24.68, 99.38 31.01 C 103.19 38.56, 102.53 50.1, 97.91 57.07 C 94.66 61.96, 89.68 64.99, 83.26 66 C 82.81 66.07, 70.18 66.83, 55.2 67.69 C 24.82 69.43, 27.03 69.23, 24.18 70.4 C 19.9 72.15, 14.84 75.7, 10.65 79.89 C 4.86 85.68, 1.3 91.91, 0.25 98.13 C 0.12 98.85, 0.08 103.13, 0.04 116.66 L 0 134.26 9.5 134.26 L 19 134.26 19.05 119.41 C 19.1 103.27, 19.08 103.82, 19.82 101.04 C 21.79 93.65, 27.86 88.75, 36.45 87.63 C 37.23 87.53, 39.41 87.5, 43.57 87.53 C 50.12 87.59, 50.75 87.65, 53.22 88.45 C 56.61 89.56, 59.67 91.86, 62.02 95.07 C 62.52 95.76, 69.35 103.85, 77.2 113.07 C 85.04 122.28, 91.63 130.04, 91.85 130.32 C 92.07 130.59, 92.5 131.34, 92.82 131.97 C 93.52 133.35, 94.11 133.93, 95.06 134.13 C 95.5 134.23, 98.97 134.26, 106.36 134.23 L 117.01 134.19 100.82 113.07 C 91.91 101.45, 84.52 91.78, 84.39 91.57 C 83.36 89.89, 83.66 87.53, 85.09 86 C 85.79 85.25, 86.36 84.94, 88.07 84.38 C 96.18 81.72, 104.15 76.62, 109.97 70.36 C 120.59 58.93, 124.06 44.32, 119.44 30.43 C 114.59 15.81, 101.93 4.02, 87.64 0.83 C 83.93 0.01, 88.09 0.08, 41.85 0.04 L 0.01 0 0.01 0.81 Z";

/** Full logo as on remocn.dev: R mark (0.76em tall, baseline-aligned) + "emocn" in Manrope 600. */
function RemocnLogo({ fontSize, color }: { fontSize: number; color: string }) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "baseline",
        color,
        fontFamily: manrope.fontFamily,
        fontWeight: 600,
        fontSize,
        letterSpacing: "-0.025em",
        lineHeight: 1,
      }}
    >
      <svg
        viewBox="0 0 124.06 134.26"
        style={{ height: "0.76em", width: "auto" }}
        aria-hidden
      >
        <path fill="currentColor" d={REMOCN_R_PATH} />
      </svg>
      <span style={{ marginLeft: "0.04em" }}>emocn</span>
    </div>
  );
}

export interface TickerTapeProps {
  /** The hero symbol the middle band stops on. */
  symbol?: string;
  /** Hero price, shown as typed. */
  price?: string;
  /** Hero move in percent; negative reads as a down move. */
  change?: number;
  /** Other (fictional) symbols filling the bands. */
  symbols?: string[];
  /** Product under the poster; "remocn" renders the real logo. */
  name?: string;
  /** Replaces the logo / name under the poster. */
  logo?: React.ReactNode;
  accent?: string;
  /** Text color of the symbols and name; overrides the theme. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the symbols and name. Load it yourself; Oswald by default. */
  fontFamily?: string;
  /** Status next to the name under the poster. */
  label?: string;
  /** Strength of the motion smear on the running bands; 0 turns it off. */
  blur?: number;
  /** Size of the bands and poster, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  /** Playback multiplier. */
  speed?: number;
  theme?: "dark" | "light";
}

// Oswald 500 advances per em for A–Z (fontTools, wght 500); cap height 0.81.
const OSWALD: Record<string, number> = {
  A: 0.522,
  B: 0.557,
  C: 0.54,
  D: 0.557,
  E: 0.428,
  F: 0.413,
  G: 0.559,
  H: 0.586,
  I: 0.275,
  J: 0.326,
  K: 0.532,
  L: 0.421,
  M: 0.683,
  N: 0.545,
  O: 0.563,
  P: 0.527,
  Q: 0.564,
  R: 0.561,
  S: 0.494,
  T: 0.43,
  U: 0.566,
  V: 0.516,
  W: 0.712,
  X: 0.499,
  Y: 0.487,
  Z: 0.425,
};
const CAP = 0.81;
/** JetBrains Mono: every glyph advances 0.6em, cap height 0.73. */
const MONO = 0.6;
const MONO_CAP = 0.73;

const symWidth = (s: string) =>
  Array.from(s).reduce((w, ch) => w + (OSWALD[ch] ?? 0.52), 0);

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_IN = Easing.bezier(0.55, 0, 0.8, 0.2);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// Beat sheet (30fps, speed 1):
//   0–40   seven bands run at full tilt, alternating directions, fast ones smear
//  40–86   everything brakes; the middle band stops dead with the hero symbol
//          centred, the others slow to a crawl
//  84–108  the side bands clear out up and down, the hero's neighbours slide
//          off, and the hero quote scales up into the poster
//  108–    poster: symbol, price, move; the thin mono tapes keep crawling
const BRAKE_AT = 40;
const STOP_AT = 86;
const RISE_AT = 84;
const RISE_LEN = 26;

// gradients.sh "aurora" (bg #03050b): #a0f0c8 #3fb5a3 #5147b6 #b25c9c.
// Up moves take the mint/teal end; the glow under the poster uses the set.
const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#7E7D84",
    rule: "rgba(243,242,239,0.1)",
    up: ["#A0F0C8", "#3FB5A3"],
    down: "#C8675E",
    glow: ["#3FB5A3", "#5147B6", "#A0F0C8"],
    glowAlpha: 0.3,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#7A7873",
    rule: "rgba(18,18,20,0.1)",
    up: ["#2E9C8B", "#5147B6"],
    down: "#B24A40",
    glow: ["#A0F0C8", "#C9C4F2", "#A0F0C8"],
    glowAlpha: 0.45,
  },
} as const;

const SYMBOLS = [
  "KTBS",
  "KEYF",
  "EASE",
  "SPRG",
  "TWEN",
  "FRMS",
  "SEQN",
  "MOTN",
  "BLUR",
  "PXLS",
  "KERN",
  "GLYF",
  "WIPE",
  "CRVE",
  "TIMR",
  "FADE",
];

function hash(n: number) {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return s - Math.floor(s);
}

interface Quote {
  sym: string;
  price: string;
  chg: number;
  hero: boolean;
}

interface Placed extends Quote {
  /** left edge inside the tile, px */
  x: number;
  w: number;
}

interface RowSpec {
  /** font size as a share of the frame height */
  size: number;
  kind: "big" | "mono";
  dir: 1 | -1;
  /** px per frame at 720p */
  v: number;
  hero?: boolean;
}

const ROWS: RowSpec[] = [
  { size: 0.026, kind: "mono", dir: -1, v: 2.6 },
  { size: 0.088, kind: "big", dir: 1, v: 7 },
  { size: 0.13, kind: "big", dir: -1, v: 11.5 },
  { size: 0.2, kind: "big", dir: -1, v: 17, hero: true },
  { size: 0.13, kind: "big", dir: 1, v: 10 },
  { size: 0.088, kind: "big", dir: -1, v: 7.5 },
  { size: 0.026, kind: "mono", dir: 1, v: 2.8 },
];

function fmtChg(c: number) {
  return `${Math.abs(c).toFixed(1)}%`;
}

/** Width of a quote at font size `fs`. Big: symbol + a two-line price/move stack. */
function quoteWidth(q: Quote, fs: number, kind: RowSpec["kind"]) {
  if (kind === "mono") {
    const chars = q.sym.length + 1 + q.price.length + 3 + fmtChg(q.chg).length;
    return chars * MONO * fs;
  }
  const sub = fs * 0.3;
  const stack = Math.max(
    q.price.length * MONO * sub,
    (fmtChg(q.chg).length + 1.4) * MONO * sub,
  );
  return symWidth(q.sym) * fs + fs * 0.16 + stack;
}

function Triangle({
  x,
  baseline,
  size,
  up,
  fill,
}: {
  x: number;
  baseline: number;
  size: number;
  up: boolean;
  fill: string;
}) {
  // sits on the cap height of the figures beside it
  const h = size * 0.56;
  const w = size * 0.62;
  const top = baseline - size * MONO_CAP + (size * MONO_CAP - h) / 2;
  const d = up
    ? `M${x} ${top + h} L${x + w / 2} ${top} L${x + w} ${top + h} Z`
    : `M${x} ${top} L${x + w} ${top} L${x + w / 2} ${top + h} Z`;
  return <path d={d} fill={fill} />;
}

function QuoteView({
  q,
  x,
  baseline,
  fs,
  kind,
  fg,
  muted,
  upFill,
  downFill,
  fontFamily,
}: {
  fontFamily: string;
  q: Quote;
  x: number;
  baseline: number;
  fs: number;
  kind: RowSpec["kind"];
  fg: string;
  muted: string;
  upFill: string;
  downFill: string;
}) {
  const up = q.chg >= 0;
  const col = up ? upFill : downFill;
  if (kind === "mono") {
    const a = x + (q.sym.length + 1) * MONO * fs;
    const b = a + (q.price.length + 1) * MONO * fs;
    return (
      <g fontFamily={mono} fontSize={fs}>
        <text x={x} y={baseline} fill={fg} fontWeight={500}>
          {q.sym}
        </text>
        <text x={a} y={baseline} fill={muted} fontWeight={400}>
          {q.price}
        </text>
        <Triangle
          x={b}
          baseline={baseline}
          size={fs}
          up={up}
          fill={up ? upFill : downFill}
        />
        <text x={b + 1.1 * MONO * fs} y={baseline} fill={col} fontWeight={400}>
          {fmtChg(q.chg)}
        </text>
      </g>
    );
  }
  const sub = fs * 0.3;
  const sx = x + symWidth(q.sym) * fs + fs * 0.16;
  const capTop = baseline - CAP * fs;
  return (
    <g>
      <text
        x={x}
        y={baseline}
        fill={fg}
        fontFamily={fontFamily}
        fontWeight={500}
        fontSize={fs}
      >
        {q.sym}
      </text>
      <g fontFamily={mono} fontSize={sub} fontWeight={400}>
        <text x={sx} y={capTop + MONO_CAP * sub} fill={muted}>
          {q.price}
        </text>
        <Triangle x={sx} baseline={baseline} size={sub} up={up} fill={col} />
        <text x={sx + 1.4 * MONO * sub} y={baseline} fill={col}>
          {fmtChg(q.chg)}
        </text>
      </g>
    </g>
  );
}

// Chrome parks a glyph raster on a whole pixel vertically for as long as the
// matrix is axis-aligned, so text under a slow transform clicks along pixel by
// pixel. The transforms that carry text are marked, so it leans off that grid
// while they move; SVG text can't carry the mark itself, so the drawing does.
const midway = (p: number) => p > 0 && p < 1;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

/** Distance travelled: full speed, then a cubic brake to `rest` × speed. */
function travel(t: number, v: number, stopAt: number, rest: number) {
  const L = stopAt - BRAKE_AT;
  if (t <= BRAKE_AT) return v * t;
  const tau = Math.min(1, (t - BRAKE_AT) / L);
  const brake = (v * (1 - rest) * L * (1 - (1 - tau) ** 3)) / 3;
  return v * BRAKE_AT + brake + v * rest * (t - BRAKE_AT);
}

function speedAt(t: number, v: number, stopAt: number, rest: number) {
  if (t <= BRAKE_AT) return v;
  const tau = Math.min(1, (t - BRAKE_AT) / (stopAt - BRAKE_AT));
  return v * rest + v * (1 - rest) * (1 - tau) ** 2;
}

export function TickerTape({
  symbol = "RMCN",
  price = "128.40",
  change = 12.4,
  symbols = SYMBOLS,
  name = "remocn",
  logo,
  accent = "#3B5BFD",
  ink,
  background,
  fontFamily = display,
  label = "MARKET CLOSE",
  blur = 1,
  scale: zoom = 1,
  delay = 0,
  speed = 1,
  theme = "dark",
}: TickerTapeProps) {
  const glide = useGlide();
  const t = Math.max(0, useCurrentFrame() - delay) * speed;
  const { width: W, height: H } = useVideoConfig();
  const u = H / 720;
  const p = THEMES[theme];
  const fg = ink ?? p.fg;
  const stage =
    background === "transparent" ? "transparent" : (background ?? p.bg);
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const heroSym = symbol.trim().toUpperCase() || "RMCN";

  // One tile of quotes per row, wide enough to cover the frame twice.
  const rows = useMemo(() => {
    let seed = 0;
    return ROWS.map((r, ri) => {
      const fs = r.size * H;
      const placed: Placed[] = [];
      let x = 0;
      const gap = r.kind === "mono" ? 2.4 * MONO * fs : fs * 0.5;
      let k = 0;
      while (x < W * 2.2 || (r.hero && k < 7)) {
        const isHero = Boolean(r.hero) && k === 5;
        const sym = isHero
          ? heroSym
          : symbols[
              (ri * 5 + k * 3 + Math.floor(hash(seed) * 4)) % symbols.length
            ];
        const up = hash(seed * 1.7 + 3) < 0.6;
        const q: Quote = isHero
          ? { sym, price, chg: change, hero: true }
          : {
              sym,
              price: (8 + hash(seed * 2.9) * 390).toFixed(2),
              chg: (up ? 1 : -1) * (0.2 + hash(seed * 4.3 + 1) * 8.6),
              hero: false,
            };
        const w = quoteWidth(q, fs, r.kind);
        placed.push({ ...q, x, w });
        x += w + gap;
        k++;
        seed++;
      }
      return { ...r, fs, placed, period: x };
    });
  }, [H, W, heroSym, price, change, symbols]);

  // vertical stack: rows separated by hairlines, centred in the frame
  const gaps = rows.map((r) => (r.kind === "mono" ? 0.03 : 0.036) * H);
  const heights = rows.map((r) => CAP * r.fs);
  const total =
    heights.reduce((a, b) => a + b, 0) +
    gaps.slice(0, -1).reduce((a, b) => a + b, 0) * 1;
  let yCursor = (H - total) / 2;
  const baselines = rows.map((_, i) => {
    const b = yCursor + heights[i];
    yCursor = b + gaps[i];
    return b;
  });

  const heroRowIdx = rows.findIndex((r) => r.hero);
  const heroRow = rows[heroRowIdx];
  const heroQ = heroRow.placed.find((q) => q.hero) as Placed;

  // poster scale and position
  const riseAt = (f: number) =>
    interpolate(f, [RISE_AT, RISE_AT + RISE_LEN], [0, 1], {
      ...CLAMP,
      easing: Easing.bezier(0.7, 0, 0.2, 1),
    });
  const rise = riseAt(t);
  const posterScale = Math.min((W * 0.74) / heroQ.w, (H * 0.36) / heroRow.fs);
  const scale = 1 + (posterScale - 1) * rise;
  const heroBaseline0 = baselines[heroRowIdx];
  const heroCy0 = heroBaseline0 - (CAP * heroRow.fs) / 2;
  const heroCy1 = H * 0.46;
  const heroCy = heroCy0 + (heroCy1 - heroCy0) * rise;

  const clearAt = (f: number) =>
    interpolate(f, [RISE_AT - 4, RISE_AT + 20], [0, 1], {
      ...CLAMP,
      easing: EASE_IN,
    });
  const clear = clearAt(t);
  const caption = (d: number) =>
    interpolate(
      t,
      [RISE_AT + RISE_LEN - 6 + d, RISE_AT + RISE_LEN + 14 + d],
      [0, 1],
      { ...CLAMP, easing: EASE_OUT },
    );
  const glowIn = interpolate(t, [RISE_AT, RISE_AT + 40], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const drift = interpolate(t, [0, 160], [0, 1], CLAMP);

  const upId = `${uid}up`;
  const upFill = `url(#${upId})`;

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {/* aurora glow lands under the poster */}
      <AbsoluteFill
        style={{
          opacity: p.glowAlpha * glowIn,
          background: p.glow
            .map(
              (c, i) =>
                `radial-gradient(30% 42% at ${22 + i * 28 + drift * 4}% ${heroCy1 / (H / 100) + (i % 2 ? 5 : -3)}%, ${c} 0%, transparent 70%)`,
            )
            .join(", "),
        }}
      />
      <ScaleLayer scale={zoom}>
        <svg
          width={W}
          height={H}
          viewBox={`0 0 ${W} ${H}`}
          style={{
            position: "absolute",
            inset: 0,
            // The bands never stop sliding, so a lean that came with the
            // poster's rise and went with it would snap their text by up to
            // half a pixel on the way; the drawing counts as moving always.
            transform: glide(true),
          }}
          role="img"
          aria-label={`${heroSym} ${price} ${change >= 0 ? "up" : "down"} ${fmtChg(change)}`}
        >
          <defs>
            <linearGradient id={upId} x1="0" y1="0" x2="1" y2="0">
              <stop offset="0" stopColor={p.up[0]} />
              <stop offset="1" stopColor={p.up[1]} />
            </linearGradient>
            <clipPath id={`${uid}stage`}>
              <rect
                x={0}
                y={baselines[0] + gaps[0] / 2}
                width={W}
                height={
                  baselines[rows.length - 1] -
                  heights[rows.length - 1] -
                  gaps[rows.length - 2] / 2 -
                  (baselines[0] + gaps[0] / 2)
                }
              />
            </clipPath>
            {rows.map((r, i) => {
              const v = speedAt(
                t,
                r.v * u,
                r.hero ? STOP_AT : STOP_AT - 8 + i * 3,
                r.hero ? 0 : 0.12,
              );
              return (
                <filter
                  key={`blur${r.size}${r.dir}${r.v}`}
                  id={`${uid}blur${i}`}
                  x="-5%"
                  y="-50%"
                  width="110%"
                  height="200%"
                >
                  <feGaussianBlur
                    stdDeviation={`${(v * 0.2 * blur).toFixed(2)} 0`}
                  />
                </filter>
              );
            })}
          </defs>

          {rows.map((r, i) => {
            const stopAt = r.hero ? STOP_AT : STOP_AT - 8 + i * 3;
            const rest = r.hero ? 0 : r.kind === "mono" ? 0.35 : 0.12;
            const D = travel(t, r.v * u, stopAt, rest);
            // the hero row is offset so the hero quote lands dead centre
            const Dstop = travel(stopAt + 1000, r.v * u, stopAt, 0);
            const x0 = r.hero
              ? W / 2 - (heroQ.x + heroQ.w / 2) - r.dir * Dstop
              : -hash(i * 3.3) * r.period;
            const shift = x0 + r.dir * D;
            const off = ((shift % r.period) + r.period) % r.period;
            const baseline = baselines[i];
            // side bands clear: upper ones up, lower ones down
            const away =
              r.kind === "mono" || r.hero
                ? 0
                : (i < heroRowIdx ? -1 : 1) * clear * H * 0.55;
            const fade = r.kind === "mono" ? 1 - 0.35 * clear : 1 - clear;
            const copies = [-1, 0, 1, 2];
            return (
              <g
                key={`row${r.size}${r.dir}${r.v}`}
                clipPath={r.kind === "mono" ? undefined : `url(#${uid}stage)`}
              >
                <g opacity={fade} transform={`translate(0 ${away})`}>
                  {/* hairlines between bands, carried away by the side bands */}
                  {i !== heroRowIdx ? (
                    <line
                      x1={0}
                      x2={W}
                      y1={
                        i < heroRowIdx
                          ? baseline + gaps[i] / 2
                          : baseline - heights[i] - gaps[i - 1] / 2
                      }
                      y2={
                        i < heroRowIdx
                          ? baseline + gaps[i] / 2
                          : baseline - heights[i] - gaps[i - 1] / 2
                      }
                      stroke={p.rule}
                      strokeWidth={Math.max(1, u)}
                    />
                  ) : null}
                  <g filter={`url(#${uid}blur${i})`}>
                    {copies.flatMap((c) =>
                      r.placed.map((q) => {
                        if (q.hero) return null;
                        let x =
                          q.x +
                          c * r.period +
                          (r.hero ? shift : off - r.period);
                        if (r.hero) {
                          // neighbours make room for the growing hero quote
                          const heroX = heroQ.x + c * r.period + shift;
                          const dirSide = x < heroX ? -1 : 1;
                          x +=
                            dirSide *
                            ((scale - 1) * heroQ.w * 0.5 + rise * W * 0.12);
                        }
                        if (x > W + 20 * u || x + q.w < -20 * u) return null;
                        return (
                          <g
                            key={`${c}-${q.x}`}
                            opacity={r.hero ? 1 - rise : 1}
                          >
                            <QuoteView
                              q={q}
                              x={x}
                              baseline={baseline}
                              fs={r.fs}
                              kind={r.kind}
                              fg={fg}
                              fontFamily={fontFamily}
                              muted={p.muted}
                              upFill={upFill}
                              downFill={p.down}
                            />
                          </g>
                        );
                      }),
                    )}
                  </g>
                </g>
              </g>
            );
          })}

          {/* hero quote: rides its band, then scales into the poster */}
          {(() => {
            const r = heroRow;
            const D = travel(t, r.v * u, STOP_AT, 0);
            const Dstop = travel(STOP_AT + 1000, r.v * u, STOP_AT, 0);
            const x0 = W / 2 - (heroQ.x + heroQ.w / 2) - r.dir * Dstop;
            const shift = x0 + r.dir * D;
            // nearest copy to the centre
            const raw = heroQ.x + shift;
            const n = Math.round((W / 2 - heroQ.w / 2 - raw) / r.period);
            const left = raw + n * r.period;
            const cx = left + heroQ.w / 2;
            return (
              <g
                transform={`translate(${cx} ${heroCy}) scale(${scale}) translate(${-cx} ${-heroCy0})`}
              >
                <g filter={`url(#${uid}blur${heroRowIdx})`}>
                  <QuoteView
                    q={heroQ}
                    x={left}
                    baseline={heroBaseline0}
                    fs={r.fs}
                    kind="big"
                    fg={fg}
                    fontFamily={fontFamily}
                    muted={p.muted}
                    upFill={upFill}
                    downFill={p.down}
                  />
                </g>
              </g>
            );
          })()}
        </svg>

        {/* caption under the poster */}
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: heroCy1 + (CAP * heroRow.fs * posterScale) / 2 + 46 * u,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            gap: 14 * u,
            fontFamily: mono,
            fontSize: 15 * u,
            letterSpacing: "0.12em",
            color: p.muted,
            lineHeight: 1,
          }}
        >
          <div
            style={{
              opacity: caption(0),
              transform: `translateY(${(1 - caption(0)) * 12 * u}px)${glide(midway(caption(0)))}`,
            }}
          >
            {logo ??
              (name.trim().toLowerCase() === "remocn" ? (
                <RemocnLogo fontSize={30 * u} color={fg} />
              ) : (
                <span
                  style={{
                    fontFamily,
                    fontWeight: 500,
                    fontSize: 30 * u,
                    letterSpacing: "0.01em",
                    color: fg,
                  }}
                >
                  {name}
                </span>
              ))}
          </div>
          <div
            style={{
              width: Math.max(1, u),
              height: 20 * u,
              background: p.rule,
              transform: `scaleY(${caption(3)})`,
            }}
          />
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 9 * u,
              opacity: caption(6),
              transform: `translateY(${(1 - caption(6)) * 12 * u}px)${glide(midway(caption(6)))}`,
            }}
          >
            <div
              style={{
                width: 7 * u,
                height: 7 * u,
                borderRadius: 99,
                background: accent,
              }}
            />
            <span>{label}</span>
          </div>
        </div>
      </ScaleLayer>
    </AbsoluteFill>
  );
}
